import{_ as a,o,c as d,a3 as t}from"./chunks/framework.BlfGB29P.js";const h=JSON.parse('{"title":"Tenant API v1 — Leads","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Tenant API v1 — Leads | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/api/tenant-v1-leads"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Tenant API v1 — Leads | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/api/tenant-v1-leads"}]]},"headers":[],"relativePath":"api/tenant-v1-leads.md","filePath":"api/tenant-v1-leads.md","lastUpdated":1786841166000}'),s={name:"api/tenant-v1-leads.md"};function i(l,e,c,r,n,p){return o(),d("div",null,[...e[0]||(e[0]=[t('<h1 id="tenant-api-v1-—-leads" tabindex="-1">Tenant API v1 — Leads <a class="header-anchor" href="#tenant-api-v1-—-leads" aria-label="Permalink to &quot;Tenant API v1 — Leads&quot;">​</a></h1><p>Base path: <code>/api/tenant/v1</code></p><p>Middleware: <code>auth:tenant-api</code>, <code>tenant.user</code>, <code>verified</code>, <code>module:leads</code>, plus permission middleware / policies.</p><p>Assignee scoping: without <code>leads.assign</code> (and not superadmin), list/board/stats/export only include leads where <code>assigned_to</code> is the current user.</p><h2 id="lead-stages" tabindex="-1">Lead stages <a class="header-anchor" href="#lead-stages" aria-label="Permalink to &quot;Lead stages&quot;">​</a></h2><h3 id="get-lead-stages" tabindex="-1">GET <code>/lead-stages</code> <a class="header-anchor" href="#get-lead-stages" aria-label="Permalink to &quot;GET `/lead-stages`&quot;">​</a></h3><p>Returns seeded pipeline stages for the workspace (New … Won / Lost).</p><h2 id="lead-tags" tabindex="-1">Lead tags <a class="header-anchor" href="#lead-tags" aria-label="Permalink to &quot;Lead tags&quot;">​</a></h2><h3 id="get-lead-tags" tabindex="-1">GET <code>/lead-tags</code> <a class="header-anchor" href="#get-lead-tags" aria-label="Permalink to &quot;GET `/lead-tags`&quot;">​</a></h3><p>Returns the workspace tag catalog (seeded on first use). Includes <code>behavior</code> (<code>none</code> | <code>auto_follow_up</code> | <code>force_follow_up</code>), <code>auto_follow_up_days</code>, <code>is_default</code>, <code>sort_order</code>, <code>color</code>.</p><h3 id="post-lead-tags" tabindex="-1">POST <code>/lead-tags</code> <a class="header-anchor" href="#post-lead-tags" aria-label="Permalink to &quot;POST `/lead-tags`&quot;">​</a></h3><p>Create a tag. Requires <code>leads.create</code>. Body: <code>name</code> (required), optional <code>slug</code>, <code>color</code>, <code>sort_order</code>, <code>is_default</code>, <code>behavior</code>, <code>auto_follow_up_days</code> (required when behavior is <code>auto_follow_up</code>).</p><h3 id="put-lead-tags-leadtag" tabindex="-1">PUT <code>/lead-tags/{leadTag}</code> <a class="header-anchor" href="#put-lead-tags-leadtag" aria-label="Permalink to &quot;PUT `/lead-tags/{leadTag}`&quot;">​</a></h3><p>Update a tag. Requires <code>leads.update</code>.</p><h3 id="delete-lead-tags-leadtag" tabindex="-1">DELETE <code>/lead-tags/{leadTag}</code> <a class="header-anchor" href="#delete-lead-tags-leadtag" aria-label="Permalink to &quot;DELETE `/lead-tags/{leadTag}`&quot;">​</a></h3><p>Hard-delete a tag and detach it from all leads. Requires <code>leads.delete</code>.</p><h3 id="post-lead-tags-reorder" tabindex="-1">POST <code>/lead-tags/reorder</code> <a class="header-anchor" href="#post-lead-tags-reorder" aria-label="Permalink to &quot;POST `/lead-tags/reorder`&quot;">​</a></h3><p>Body: <code>{ &quot;ordered_ids&quot;: number[] }</code>. Requires <code>leads.update</code>.</p><h3 id="put-leads-lead-tags" tabindex="-1">PUT <code>/leads/{lead}/tags</code> <a class="header-anchor" href="#put-leads-lead-tags" aria-label="Permalink to &quot;PUT `/leads/{lead}/tags`&quot;">​</a></h3><p>Sync tags on a lead. Body: <code>{ &quot;tag_ids&quot;: number[], &quot;follow_up&quot;?: { title, due_at, notes?, assigned_to? } }</code>. Requires <code>leads.update</code>. Newly added <code>force_follow_up</code> tags require <code>follow_up</code>. Newly added <code>auto_follow_up</code> tags create a pending follow-up due in <code>auto_follow_up_days</code> (workspace timezone) unless one already exists for that lead+tag (<code>lead_follow_ups.lead_tag_id</code>). Applying tags never changes stage or status.</p><h2 id="stats-board" tabindex="-1">Stats &amp; board <a class="header-anchor" href="#stats-board" aria-label="Permalink to &quot;Stats &amp; board&quot;">​</a></h2><h3 id="get-leads-stats" tabindex="-1">GET <code>/leads/stats</code> <a class="header-anchor" href="#get-leads-stats" aria-label="Permalink to &quot;GET `/leads/stats`&quot;">​</a></h3><p>Same filters as list (minus pagination/sort). Payload includes:</p><p><code>total_leads</code>, <code>my_leads</code>, <code>pipeline_value</code>, <code>todays_follow_ups</code>, <code>overdue_follow_ups</code>, <code>won_this_month</code>, <code>average_lead_value</code>, <code>conversion_rate</code>, <code>scope</code> (<code>org</code>|<code>mine</code>).</p><p>Pipeline / won metrics use stage <code>is_won</code> / <code>is_lost</code> flags, not lead status.</p><h3 id="get-leads-board" tabindex="-1">GET <code>/leads/board</code> <a class="header-anchor" href="#get-leads-board" aria-label="Permalink to &quot;GET `/leads/board`&quot;">​</a></h3><p>Columns per stage: <code>stage</code>, <code>lead_count</code>, <code>total_lead_value</code>, <code>leads[]</code>. Honors the same filters as list.</p><h2 id="leads-crud" tabindex="-1">Leads CRUD <a class="header-anchor" href="#leads-crud" aria-label="Permalink to &quot;Leads CRUD&quot;">​</a></h2><h3 id="get-leads" tabindex="-1">GET <code>/leads</code> <a class="header-anchor" href="#get-leads" aria-label="Permalink to &quot;GET `/leads`&quot;">​</a></h3><p>Query: <code>search</code>, <code>status</code>, <code>stage_id</code>, <code>tag_id</code>, <code>tag_ids</code> (comma-separated), <code>priority</code>, <code>assigned_to</code> (<code>unassigned</code> or user id), <code>lead_value_min</code>, <code>lead_value_max</code>, <code>trashed</code>, <code>sort</code>, <code>direction</code>, <code>page</code>, <code>per_page</code>.</p><p>Status values: <code>active</code>, <code>waiting</code>, <code>on_hold</code>, <code>closed</code>, <code>archived</code>.</p><p>List and board lead cards include:</p><ul><li><code>tags</code> — applied tag objects (<code>id</code>, <code>name</code>, <code>slug</code>, <code>color</code>, <code>behavior</code>, …)</li><li><code>latest_note</code> — most recent note (<code>id</code>, <code>body</code>, <code>author</code>, timestamps) or <code>null</code></li><li><code>next_follow_up</code> — earliest pending follow-up (<code>id</code>, <code>title</code>, <code>notes</code>, <code>due_at</code>, <code>status</code>, <code>assignee</code>, …) or <code>null</code></li><li><code>next_follow_up_at</code> — denormalized due timestamp for the next pending follow-up (unchanged)</li></ul><h3 id="post-leads" tabindex="-1">POST <code>/leads</code> <a class="header-anchor" href="#post-leads" aria-label="Permalink to &quot;POST `/leads`&quot;">​</a></h3><p>Body: <code>name</code> (required), <code>lead_type</code> (required: <code>direct</code> | <code>company</code>), <code>email</code>, <code>phone</code>, <code>company</code>, <code>job_title</code>, <code>source</code>, <code>lead_value</code> (or legacy alias <code>estimated_value</code>), <code>priority</code>, <code>status</code>, <code>stage_id</code>, <code>assigned_to</code>, optional <code>tag_ids</code> (defaults to workspace default tags; type tags are merged automatically), optional <code>follow_up</code> when creating with a force-follow-up tag.</p><h3 id="get-leads-id" tabindex="-1">GET <code>/leads/{id}</code> <a class="header-anchor" href="#get-leads-id" aria-label="Permalink to &quot;GET `/leads/{id}`&quot;">​</a></h3><p>Includes stage, assignee, tags, notes, follow-ups, activities, assignment histories. Exposes <code>converted_at</code> / <code>is_converted</code>.</p><h3 id="put-leads-id" tabindex="-1">PUT <code>/leads/{id}</code> <a class="header-anchor" href="#put-leads-id" aria-label="Permalink to &quot;PUT `/leads/{id}`&quot;">​</a></h3><p>Partial update of lead fields (including <code>lead_type</code>, <code>stage_id</code>, <code>status</code>, <code>priority</code>, <code>lead_value</code>, <code>assigned_to</code>). Changing <code>lead_type</code> swaps the exclusive Direct Lead / Company Lead system tags. Stage change does <strong>not</strong> sync status.</p><h3 id="delete-leads-id" tabindex="-1">DELETE <code>/leads/{id}</code> <a class="header-anchor" href="#delete-leads-id" aria-label="Permalink to &quot;DELETE `/leads/{id}`&quot;">​</a></h3><p>Soft delete. Permission: <code>leads.delete</code>.</p><h3 id="post-leads-id-restore" tabindex="-1">POST <code>/leads/{id}/restore</code> <a class="header-anchor" href="#post-leads-id-restore" aria-label="Permalink to &quot;POST `/leads/{id}/restore`&quot;">​</a></h3><p>Restore a soft-deleted lead. Permission: <code>leads.restore</code> (admin + owner by default).</p><h3 id="delete-leads-id-force" tabindex="-1">DELETE <code>/leads/{id}/force</code> <a class="header-anchor" href="#delete-leads-id-force" aria-label="Permalink to &quot;DELETE `/leads/{id}/force`&quot;">​</a></h3><p>Permanently delete a soft-deleted lead (must already be trashed). Permission: <code>leads.force.delete</code> (owner by default).</p><h2 id="export" tabindex="-1">Export <a class="header-anchor" href="#export" aria-label="Permalink to &quot;Export&quot;">​</a></h2><h3 id="get-leads-export" tabindex="-1">GET <code>/leads/export</code> <a class="header-anchor" href="#get-leads-export" aria-label="Permalink to &quot;GET `/leads/export`&quot;">​</a></h3><p>Permission: <code>leads.export</code>.</p><p>Query: same filters as list, plus <code>format</code> = <code>csv</code> (default) or <code>xlsx</code>. Streams a download of the filtered set.</p><h2 id="import" tabindex="-1">Import <a class="header-anchor" href="#import" aria-label="Permalink to &quot;Import&quot;">​</a></h2><p>Permission for all import routes: <code>leads.import</code> (+ <code>module:leads</code>).</p><p>Duplicate mode <code>update</code> also requires <code>leads.update</code>.</p><h3 id="get-leads-import-template" tabindex="-1">GET <code>/leads/import/template</code> <a class="header-anchor" href="#get-leads-import-template" aria-label="Permalink to &quot;GET `/leads/import/template`&quot;">​</a></h3><p>Query: <code>format</code> = <code>csv</code> (default) or <code>xlsx</code>. Downloads a sample template with all mappable columns (including optional <strong>Note</strong>) and one sample row.</p><h3 id="get-leads-imports" tabindex="-1">GET <code>/leads/imports</code> <a class="header-anchor" href="#get-leads-imports" aria-label="Permalink to &quot;GET `/leads/imports`&quot;">​</a></h3><p>Paginated import history (status, user, file name, row counts, timestamps).</p><h3 id="post-leads-imports" tabindex="-1">POST <code>/leads/imports</code> <a class="header-anchor" href="#post-leads-imports" aria-label="Permalink to &quot;POST `/leads/imports`&quot;">​</a></h3><p>Multipart: <code>file</code> (CSV/XLSX). Stores the upload, returns import record + <code>context</code> (headers, sample rows, suggested mapping, fields). Status: <code>uploaded</code>.</p><h3 id="put-leads-imports-uuid" tabindex="-1">PUT <code>/leads/imports/{uuid}</code> <a class="header-anchor" href="#put-leads-imports-uuid" aria-label="Permalink to &quot;PUT `/leads/imports/{uuid}`&quot;">​</a></h3><p>Body: <code>{ &quot;mapping&quot;: { &quot;name&quot;: &quot;Name&quot;, &quot;email&quot;: &quot;Email&quot;, &quot;note&quot;: &quot;Note&quot;, ... } }</code>. Status → <code>mapped</code>.</p><p>Mappable system fields include lead attributes plus optional <code>note</code> (max 5000 chars). A non-empty note creates a lead note authored by the importer after create; on duplicate mode <code>update</code> it appends a note. Empty note cells are ignored.</p><h3 id="put-leads-imports-uuid-options" tabindex="-1">PUT <code>/leads/imports/{uuid}/options</code> <a class="header-anchor" href="#put-leads-imports-uuid-options" aria-label="Permalink to &quot;PUT `/leads/imports/{uuid}/options`&quot;">​</a></h3><p>Body: <code>{ &quot;unique_fields&quot;: [&quot;email&quot;,&quot;phone&quot;], &quot;duplicate_mode&quot;: &quot;skip&quot;|&quot;update&quot;|&quot;keep&quot;, &quot;assignment_mode&quot;: &quot;none&quot;|&quot;equal&quot; }</code>.</p><p><code>duplicate_mode=update</code> requires <code>leads.update</code>. <code>assignment_mode=equal</code> requires <code>leads.assign</code> <strong>and</strong> that the actor is <code>manager_id</code> on at least one active department; newly created leads are distributed equally among eligible members of those managed department(s).</p><p>Same-day duplicate detection (workspace timezone): when a row matches email/phone on a lead created today, the <strong>Duplicate</strong> tag is applied and <code>lead.duplicate_detected</code> notifications are sent — regardless of duplicate mode (including <strong>skip</strong>).</p><h3 id="post-leads-imports-uuid-preview" tabindex="-1">POST <code>/leads/imports/{uuid}/preview</code> <a class="header-anchor" href="#post-leads-imports-uuid-preview" aria-label="Permalink to &quot;POST `/leads/imports/{uuid}/preview`&quot;">​</a></h3><p>Validates rows without writing leads. Returns preview counts + sample validation errors.</p><h3 id="post-leads-imports-uuid-run" tabindex="-1">POST <code>/leads/imports/{uuid}/run</code> <a class="header-anchor" href="#post-leads-imports-uuid-run" aria-label="Permalink to &quot;POST `/leads/imports/{uuid}/run`&quot;">​</a></h3><p>Queues <code>ProcessLeadImportJob</code> on the <code>imports</code> queue. Status → <code>queued</code> → <code>processing</code> → <code>completed</code>|<code>failed</code>. Poll <code>GET /leads/imports/{uuid}</code>.</p><h3 id="get-leads-imports-uuid" tabindex="-1">GET <code>/leads/imports/{uuid}</code> <a class="header-anchor" href="#get-leads-imports-uuid" aria-label="Permalink to &quot;GET `/leads/imports/{uuid}`&quot;">​</a></h3><p>Status + statistics for polling (<code>processed_rows</code> / <code>total_rows</code>, imported/updated/skipped/duplicate/failed counts).</p><h3 id="get-leads-imports-uuid-file" tabindex="-1">GET <code>/leads/imports/{uuid}/file</code> <a class="header-anchor" href="#get-leads-imports-uuid-file" aria-label="Permalink to &quot;GET `/leads/imports/{uuid}/file`&quot;">​</a></h3><p>Download the original uploaded file.</p><h3 id="get-leads-imports-uuid-failed-records" tabindex="-1">GET <code>/leads/imports/{uuid}/failed-records</code> <a class="header-anchor" href="#get-leads-imports-uuid-failed-records" aria-label="Permalink to &quot;GET `/leads/imports/{uuid}/failed-records`&quot;">​</a></h3><p>Download <code>failed_records.csv</code> (original row + reason + validation errors).</p><h3 id="get-leads-imports-uuid-error-report" tabindex="-1">GET <code>/leads/imports/{uuid}/error-report</code> <a class="header-anchor" href="#get-leads-imports-uuid-error-report" aria-label="Permalink to &quot;GET `/leads/imports/{uuid}/error-report`&quot;">​</a></h3><p>Download <code>error_report.csv</code> (technical/processing exceptions).</p><h2 id="actions" tabindex="-1">Actions <a class="header-anchor" href="#actions" aria-label="Permalink to &quot;Actions&quot;">​</a></h2><h3 id="post-leads-id-assign" tabindex="-1">POST <code>/leads/{id}/assign</code> <a class="header-anchor" href="#post-leads-id-assign" aria-label="Permalink to &quot;POST `/leads/{id}/assign`&quot;">​</a></h3><p><code>{ &quot;assigned_to&quot;: number|null, &quot;reason&quot;?: string }</code> — records assignment history.</p><p><code>assigned_to</code> must be an <strong>eligible</strong> assignee (not suspended, not workspace owner, not <code>exclude_from_lead_auto_assign</code>), or <code>null</code> to unassign.</p><h3 id="post-leads-id-stage" tabindex="-1">POST <code>/leads/{id}/stage</code> <a class="header-anchor" href="#post-leads-id-stage" aria-label="Permalink to &quot;POST `/leads/{id}/stage`&quot;">​</a></h3><p><code>{ &quot;stage_id&quot;: number }</code> — updates stage only (status unchanged).</p><h3 id="post-leads-id-convert" tabindex="-1">POST <code>/leads/{id}/convert</code> <a class="header-anchor" href="#post-leads-id-convert" aria-label="Permalink to &quot;POST `/leads/{id}/convert`&quot;">​</a></h3><p>Permission: <code>leads.convert</code> (assignee-scoped like update unless the actor has <code>leads.assign</code> / owner). Creating related records also requires the matching create permission when that module is entitled:</p><table tabindex="0"><thead><tr><th>Related create / link</th><th>Permission</th></tr></thead><tbody><tr><td>Contact</td><td><code>contacts.create</code></td></tr><tr><td>Company (new name only)</td><td><code>companies.create</code></td></tr><tr><td>Opportunity (<code>create_opportunity: true</code>)</td><td><code>opportunities.create</code></td></tr><tr><td>Link existing stub opportunity on contact backfill</td><td><code>opportunities.update</code></td></tr></tbody></table><p>Optional body:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;notes&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;string|null&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;create_opportunity&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;opportunity&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;required when create_opportunity is true&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;amount&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">null</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;currency&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;USD&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;probability&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">null</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;expected_close_date&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">null</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;stage_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">null</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Sets <code>converted_at</code>, <code>conversion_meta</code>, status <code>closed</code>, and a converted activity. When the workspace has the <strong>Contacts</strong> module installed, this also creates (or reuses) a real <code>Contact</code>, links it via <code>contact_id</code>/<code>contact</code>, preserves the lead assignee, and sets <code>conversion_meta.stub = false</code>. When <strong>Companies</strong> is installed and the lead has a company name, creates or reuses a Company (case-insensitive name) and stores <code>conversion_meta.company_id</code> (and Contact <code>company_id</code>). When <strong>Opportunities</strong> is installed and <code>create_opportunity</code> is true, creates an Opportunity linked to the lead/contact/company and stores <code>conversion_meta.opportunity_id</code>. Stub converts without a <code>contact_id</code> may call convert again after Contacts is installed to backfill the contact. Without Contacts installed, conversion remains status-only for contacts (<code>conversion_meta.stub = true</code>) but may still create company/opportunity. See <a href="/api/tenant-v1-contacts">tenant-v1-contacts.md</a>, <a href="/api/tenant-v1-companies">tenant-v1-companies.md</a>, <a href="/api/tenant-v1-opportunities">tenant-v1-opportunities.md</a>.</p><h3 id="post-leads-id-notes" tabindex="-1">POST <code>/leads/{id}/notes</code> <a class="header-anchor" href="#post-leads-id-notes" aria-label="Permalink to &quot;POST `/leads/{id}/notes`&quot;">​</a></h3><p><code>{ &quot;body&quot;: string }</code></p><h3 id="post-leads-id-follow-ups" tabindex="-1">POST <code>/leads/{id}/follow-ups</code> <a class="header-anchor" href="#post-leads-id-follow-ups" aria-label="Permalink to &quot;POST `/leads/{id}/follow-ups`&quot;">​</a></h3><p><code>{ &quot;title&quot;, &quot;due_at&quot;, &quot;notes?&quot;, &quot;assigned_to?&quot; }</code></p><h3 id="put-leads-id-follow-ups-followupid" tabindex="-1">PUT <code>/leads/{id}/follow-ups/{followUpId}</code> <a class="header-anchor" href="#put-leads-id-follow-ups-followupid" aria-label="Permalink to &quot;PUT `/leads/{id}/follow-ups/{followUpId}`&quot;">​</a></h3><p>Partial update (<code>title</code>, <code>due_at</code>, <code>notes</code>, <code>assigned_to</code>). Changing <code>due_at</code> is treated as a reschedule in the activity timeline.</p><h3 id="post-leads-id-follow-ups-followupid-complete" tabindex="-1">POST <code>/leads/{id}/follow-ups/{followUpId}/complete</code> <a class="header-anchor" href="#post-leads-id-follow-ups-followupid-complete" aria-label="Permalink to &quot;POST `/leads/{id}/follow-ups/{followUpId}/complete`&quot;">​</a></h3><p>Marks follow-up completed.</p><h3 id="get-leads-id-timeline" tabindex="-1">GET <code>/leads/{id}/timeline</code> <a class="header-anchor" href="#get-leads-id-timeline" aria-label="Permalink to &quot;GET `/leads/{id}/timeline`&quot;">​</a></h3><p>CRM activity timeline entries.</p><h3 id="get-leads-id-assignment-history" tabindex="-1">GET <code>/leads/{id}/assignment-history</code> <a class="header-anchor" href="#get-leads-id-assignment-history" aria-label="Permalink to &quot;GET `/leads/{id}/assignment-history`&quot;">​</a></h3><p>Ordered assignment change rows (<code>old_user</code>, <code>new_user</code>, <code>changed_by</code>, <code>reason</code>, timestamps).</p><h2 id="integrations-leads-manage-integrations" tabindex="-1">Integrations (<code>leads.manage_integrations</code>) <a class="header-anchor" href="#integrations-leads-manage-integrations" aria-label="Permalink to &quot;Integrations (`leads.manage_integrations`)&quot;">​</a></h2><h3 id="webhooks" tabindex="-1">Webhooks <a class="header-anchor" href="#webhooks" aria-label="Permalink to &quot;Webhooks&quot;">​</a></h3><ul><li><code>GET/POST /leads/integrations/webhooks</code></li><li><code>PUT /leads/integrations/webhooks/{id}</code></li><li><code>POST /leads/integrations/webhooks/{id}/rotate</code></li><li><code>DELETE /leads/integrations/webhooks/{id}</code></li></ul><p>Create/rotate responses include plaintext <code>api_key</code> and <code>signing_secret</code> once. Public ingress: <code>POST /webhooks/leads/custom/{uuid}</code> (Bearer or <code>X-EloSync-Signature</code>). Endpoint fields include <code>assign_to_website_recipients</code> (boolean, default <code>false</code>). See <a href="/developer-guide/custom-lead-webhook">Custom Lead Webhook</a>.</p><h3 id="meta-lead-ads" tabindex="-1">Meta Lead Ads <a class="header-anchor" href="#meta-lead-ads" aria-label="Permalink to &quot;Meta Lead Ads&quot;">​</a></h3><ul><li><code>GET/PATCH /leads/integrations/meta</code> — includes <code>available_pages</code> when connected</li><li><code>GET /leads/integrations/meta/pages</code> — refresh candidate Pages (id/name only)</li><li><code>GET /leads/integrations/meta/oauth/redirect</code></li><li><code>POST /leads/integrations/meta/pages</code> — body <code>{ page_ids: string[] }</code> (empty clears subscriptions)</li><li><code>POST /leads/integrations/meta/disconnect</code> — force-deletes page rows so IDs can be reclaimed</li></ul><p>OAuth callback: <code>GET /api/oauth/leads/meta/callback</code>. Shared webhook: <code>GET/POST /webhooks/leads/meta</code>. Operator setup: <a href="/developer-guide/meta-app-setup">Meta App Setup</a>. Architecture: <a href="/developer-guide/meta-lead-ads-integration">Meta Lead Ads</a>.</p>',108)])])}const m=a(s,[["render",i]]);export{h as __pageData,m as default};
